#include <stdio.h>
#include <stdarg.h>

int span(int count, ...) {
    va_list args;
    va_start(args, count);
    int first = va_arg(args, int);
    int lo = first, hi = first;
    for (int i = 1; i < count; i++) {
        int v = va_arg(args, int);
        if (v < lo) lo = v;
        if (v > hi) hi = v;
    }
    va_end(args);
    return hi - lo;
}

int main(void) {
    int a, b, c, d, e;
    scanf("%d %d %d %d %d", &a, &b, &c, &d, &e);
    printf("%d\n", span(5, a, b, c, d, e));
    printf("%d\n", span(3, a, b, c));
    printf("%d\n", span(1, e));
    return 0;
}
